def bits(v, w):
    return '"' + format(v & ((1 << w) - 1), '0' + str(w) + 'b') + '"'


def arr(name, typ, vals, w, per=32):
    rows = [', '.join(bits(v, w) for v in vals[i:i + per]) for i in range(0, len(vals), per)]
    return '    constant ' + name + ' : ' + typ + ' := (\n        ' + ',\n        '.join(rows) + '\n    );'


def emit():
    q = [int(SCENE_Q[i:i + 2], 16) for i in range(0, len(SCENE_Q), 2)]
    hq = [int(c, 16) for c in SCENE_H]
    cs = []
    for b in range(4):
        rp, cp = b >> 1, b & 1
        vals = [q[(2 * ra + rp) * 64 + 2 * ca + cp] for ra in range(64) for ca in range(32)]
        cs.append(arr('C_S%dH' % b, 't_rom4', [v >> 2 for v in vals], 4))
        cs.append(arr('C_S%dL' % b, 't_rom2', [v & 3 for v in vals], 2))
    cs.append(arr('C_SHUE', 't_hue', hq, 2, 64))
    fn = ['    function f_pal(a : unsigned(3 downto 0)) return std_logic_vector is',
          '    begin', '        case to_integer(a) is']
    for e in range(16):
        if e in (6, 7, 12, 13, 14, 15):
            continue
        y, u, v = PALS[0][e]
        fn.append('            when %2d => return "%s%s%s";' % (e, format(y, '08b'), format(u, '08b'), format(v, '08b')))
    fn += ['            when others => return x"108080";', '        end case;', '    end function;']
    types = ''
    txt = ('-- rorschach_pkg.vhd -- GENERATED by rorschach.py; edit the generator, not this file.\n'
           '-- C_S<b>H/L: scene phase banks (4 + 2 bits).  C_SHUE: scene dark-band hue.\n'
           '-- f_pal: palette (8 x 16) as logic.\n\n'
           'library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n\npackage rorschach_pkg is\n'
           '    type t_rom4 is array(0 to 2047) of std_logic_vector(3 downto 0);\n'
           '    type t_rom2 is array(0 to 2047) of std_logic_vector(1 downto 0);\n'
           '    type t_hue is array(0 to 4095) of std_logic_vector(1 downto 0);\n' + types + '\n' +
           '\n'.join(cs) + '\n    function f_pal(a : unsigned(3 downto 0)) return std_logic_vector;\n'
           'end package rorschach_pkg;\n\npackage body rorschach_pkg is\n' + '\n'.join(fn) +
           '\nend package body rorschach_pkg;\n')
    with open(os.path.join(HERE, 'rorschach_pkg.vhd'), 'w') as fh:
        fh.write(txt)


if __name__ == '__main__':
    emit()
